DROP TRIGGER IF EXISTS products_fts_ai;
--> statement-breakpoint
DROP TRIGGER IF EXISTS products_fts_au;
--> statement-breakpoint
DROP TRIGGER IF EXISTS products_fts_ad;
--> statement-breakpoint
DROP TABLE IF EXISTS products_fts;
--> statement-breakpoint
CREATE VIRTUAL TABLE products_fts USING fts5(title, description, slug);
--> statement-breakpoint
INSERT INTO products_fts(rowid, title, description, slug) SELECT rowid, title, description_text, slug FROM products;
--> statement-breakpoint
CREATE TRIGGER products_fts_ai AFTER INSERT ON products BEGIN INSERT INTO products_fts(rowid, title, description, slug) VALUES (new.rowid, new.title, new.description_text, new.slug); END;
--> statement-breakpoint
CREATE TRIGGER products_fts_au AFTER UPDATE ON products BEGIN DELETE FROM products_fts WHERE rowid = old.rowid; INSERT INTO products_fts(rowid, title, description, slug) VALUES (new.rowid, new.title, new.description_text, new.slug); END;
--> statement-breakpoint
CREATE TRIGGER products_fts_ad AFTER DELETE ON products BEGIN DELETE FROM products_fts WHERE rowid = old.rowid; END;
